INSERT INTO feature VALUES('tactics-over-goals','metaprograms','Tactics over goals (~t)','typed-holes','partial','notable',NULL,'A splice `~t` written where a value is read is a hole the checker fills by running the tactic `t` at the goal the hole stands at, the binders in scope with their types and the type the value is checked against: `assumption` answers the innermost binder whose type converts with the goal, and `intro(t)` a function whose body is `t`''s answer under the binder it introduces, each new goal stated under the binders before it. The answer is judged against the goal again and written in the hole''s place, so the kernel replays the filled declaration and no tactic is trusted; a goal no binder answers, an introduction where no function is asked and a splice with no type to check it against are refused `TacticRefused`, and an operand that writes no tactic `UnknownTactic`. Tactics written in gandr, over codes of terms, wait on #2787.','core-term core-checker surface-grammar surface-lowering','corpus/model/metaprograms/tactics-over-goals.gandr corpus/pathological/metaprograms/tactics-over-goals.gandr crates/core-checker-base/tests/tactic.rs','corpus/ledger/features/tactics-over-goals.gandr','#2787');
